function perform(input, context) {
    let hostClassLookup;

    try {
        Java.type('java.lang.System');

        hostClassLookup = 'allowed';
    } catch (error) {
        hostClassLookup = 'blocked: ' + error.message;
    }

    return {
        mode: 'strict',
        greeting: 'Hello, ' + input.name + '!',
        hostClassLookup,
    };
}

function perform(input, context) {
    const System = Java.type('java.lang.System');
    const Runtime = Java.type('java.lang.Runtime');

    const runtime = Runtime.getRuntime();

    return {
        mode: 'trusted',
        greeting: 'Hello, ' + input.name + '!',
        hostClassLookup: 'allowed',
        server: {
            javaVersion: String(System.getProperty('java.version')),
            osName: String(System.getProperty('os.name')),
            availableProcessors: runtime.availableProcessors(),
            maxMemoryMegabytes: Math.round(runtime.maxMemory() / (1024 * 1024)),
        },
    };
}

import java


def perform(input, context):
    system = java.type("java.lang.System")
    runtime = java.type("java.lang.Runtime").getRuntime()

    return {
        "mode": "trusted",
        "greeting": "Hello, " + input["name"] + "!",
        "hostClassLookup": "allowed",
        "server": {
            "javaVersion": str(system.getProperty("java.version")),
            "osName": str(system.getProperty("os.name")),
            "availableProcessors": int(runtime.availableProcessors()),
            "maxMemoryMegabytes": round(runtime.maxMemory() / (1024 * 1024)),
        },
    }
